writeFileSync(
	join(agentDir, "herdr-agents", "config.json"),
	JSON.stringify({
		...example,
		models: {
			default: "fake/pi-default",
			agents: { "hs-pi-open": "fake/pi-agent-default" },
		},
	}),
);

const {
	api,
	commands,
	ctxFor,
	registered,
	resultFor,
	resume,
	start,
	testApi,
	useHerdr,
	userMessages,
	waitForMessage,
	writeRole,
} = await import("./native-flow-harness.ts");
const { scratch } = await import("./native-fixtures.ts");
